def breadcrumb(items):
    parts=['<a href="index.html" class="hover:text-[#082f72]">Início</a>']
    for label,href in items[:-1]: parts.append(f'<a href="{href}" class="hover:text-[#082f72]">{escape(label)}</a>')
    parts.append(f'<span aria-current="page" class="font-bold text-[#082f72]">{escape(items[-1][0])}</span>')
    return '<nav aria-label="Breadcrumb" class="flex flex-wrap items-center gap-2 text-xs font-semibold uppercase tracking-[.1em] text-[#657083]">' + '<i class="ph ph-caret-right text-[10px]" aria-hidden="true"></i>'.join(parts) + '</nav>'


