def context_strip(parent_label,parent_href,current,links=None):
    links=links or []
    items=''.join([f'<a href="{href}" class="inline-flex min-h-10 items-center border border-[#082f72]/15 bg-white px-4 text-sm font-semibold text-[#082f72] hover:border-[#e5187e] hover:text-[#e5187e]">{label}</a>' for label,href in links])
    return f'''
<div class="border-b border-[#082f72]/10 bg-[#f7f6ef]">
  <div class="mx-auto flex max-w-[1200px] flex-col gap-3 px-5 py-4 sm:flex-row sm:items-center sm:justify-between lg:px-8">
    <div class="flex items-center gap-2 text-sm"><a href="{parent_href}" class="font-bold text-[#082f72]">{parent_label}</a><i class="ph ph-caret-right text-xs text-[#6b7484]"></i><span class="text-[#6b7484]">{current}</span></div>
    {f'<div class="flex flex-wrap gap-2">{items}</div>' if items else ''}
  </div>
</div>'''


def subtle_continue(title, text, links):
    lis=''.join([f'<a href="{href}" class="group flex items-center justify-between border-t border-[#082f72]/12 py-5 text-[#082f72] first:border-t-0"><span><b class="block text-lg">{label}</b>{f"<span class=\"mt-1 block text-sm text-[#657083]\">{sub}</span>" if sub else ""}</span><i class="ph ph-arrow-right text-xl transition group-hover:translate-x-1"></i></a>' for label,href,sub in links])
    return f'''
<section class="px-5 py-16 lg:px-8"><div class="mx-auto max-w-[1000px] border-y border-[#082f72]/12 py-8"><div class="grid gap-8 md:grid-cols-[.7fr_1.3fr]"><div><p class="text-xs font-bold uppercase tracking-[.16em] text-[#e5187e]">Continue</p><h2 class="mt-3 font-display text-4xl font-extrabold uppercase italic leading-[.85] text-[#082f72]">{title}</h2><p class="mt-4 text-base leading-relaxed text-[#657083]">{text}</p></div><div>{lis}</div></div></div></section>'''


