# DOCUMENT/UTILITY HELPERS
def doc_page(title,eyebrow,intro,sections,active=''):
    c=support_header(title,eyebrow,intro,[(title,f'{title.lower().replace(" ","-")}.html')])
    body=''.join([f'<section class="border-t border-[#082f72]/10 py-8 first:border-t-0"><h2 class="text-2xl font-bold text-[#082f72]">{h}</h2><div class="mt-4 space-y-4 text-lg leading-[1.75] text-[#4e5b6e]">{p}</div></section>' for h,p in sections])
    c+=f'<article class="bg-white px-5 py-14 lg:px-8"><div class="mx-auto max-w-[780px]">{body}</div></article>'
    return page(title,active,c)

